Object.keys(editorialContent).forEach(locale=>Object.assign(translations[locale],editorialContent[locale]));
let language='en';try{const saved=localStorage.getItem('jarvis-language');if(translations[saved])language=saved;}catch{}
const select=document.querySelector('#language');function setLanguage(value){language=translations[value]?value:'en';const strings=translations[language];document.documentElement.lang=language;document.title=strings.title;document.querySelector('meta[name="description"]').content=strings.metaDescription;select.value=language;document.querySelectorAll('[data-t]').forEach(el=>{el.innerHTML=strings[el.dataset.t];});document.querySelectorAll('[data-label]').forEach(el=>el.setAttribute('aria-label',strings[el.dataset.label]));const frame=document.querySelector('iframe');if(frame)frame.title=strings.videotitle;try{localStorage.setItem('jarvis-language',language);}catch{}}select.addEventListener('change',e=>setLanguage(e.target.value));setLanguage(language);
const dialog=document.querySelector('#player'),container=document.querySelector('#video-container');document.querySelectorAll('[data-video]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#player-title').textContent=button.dataset.title;document.querySelector('#player-link').href='https://www.youtube.com/watch?v='+button.dataset.video;const frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+button.dataset.video+'?rel=0';frame.title=translations[language].videotitle;frame.allow='encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';container.replaceChildren(frame);dialog.showModal();}));document.querySelector('#close-player').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>container.replaceChildren());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
